// Product Categories
export interface ProductCategory {
  id: string
  name: string
  slug: string
  description: string
  image: string
  subcategories?: ProductSubcategory[]
}

export interface ProductSubcategory {
  id: string
  name: string
  slug: string
  products: Product[]
}

export interface Product {
  id: string
  name: string
  slug: string
  categoryId: string
  subcategoryId: string
  description: string
  shortDescription: string
  image: string
  gallery?: string[]
  specifications: ProductSpecification
  exportSeason: ExportSeason
  packaging: PackagingOption[]
  cartonSpec: CartonSpecification
  storage: StorageInfo
  exportedTo: ExportedCountry[]
  isBestSelling: boolean
  isSeasonal: boolean
}

export interface ProductSpecification {
  productName: string
  scientificName?: string
  category: string
  origin: string
  countryOfOrigin: string
  variety?: string
  color?: string
  shape?: string
  size?: string
  diameter?: string
  weight?: string
  taste?: string
  texture?: string
  moistureLevel?: string
  maturity?: string
  qualityGrade: string
  exportGrade: string
  shelfLife: string
  storageTemperature: string
  humidityRecommendation?: string
  transportationMethod: string
  availability: string
}

export interface ExportSeason {
  availableMonths: number[]
  peakExportMonths: number[]
  offSeason: number[]
}

export interface PackagingOption {
  type: string
  description: string
  image?: string
}

export interface CartonSpecification {
  cartonSize: string
  netWeight: string
  grossWeight: string
  dimensions: string
  piecesPerCarton: string
  cartonsPerPallet: string
}

export interface StorageInfo {
  storageTemperature: string
  humidity: string
  shippingMethod: string
  refrigeratedContainer: string
  shelfLifeDuringShipping: string
}

export interface ExportedCountry {
  name: string
  code: string
}

