// Helper functions
export function getProductsByCategory(categoryId: string): Product[] {
  return products.filter((p) => p.categoryId === categoryId)
}

export function getProductsBySubcategory(categoryId: string, subcategoryId: string): Product[] {
  return products.filter((p) => p.categoryId === categoryId && p.subcategoryId === subcategoryId)
}

export function getProductBySlug(slug: string): Product | undefined {
  return products.find((p) => p.slug === slug)
}

export function getBestSellingProducts(): Product[] {
  return products.filter((p) => p.isBestSelling)
}

export function getSeasonalProducts(): Product[] {
  return products.filter((p) => p.isSeasonal)
}

export function getRelatedProducts(product: Product, limit: number = 4): Product[] {
  const sameSubcategory = products.filter(
    (p) =>
      p.id !== product.id &&
      p.categoryId === product.categoryId &&
      p.subcategoryId === product.subcategoryId
  )
  const sameCategory = products.filter(
    (p) => p.id !== product.id && p.categoryId === product.categoryId
  )

  return [...sameSubcategory, ...sameCategory.filter((p) => p.subcategoryId !== product.subcategoryId)].slice(
    0,
    limit
  )
}

export function searchProducts(query: string): Product[] {
  const lowerQuery = query.toLowerCase()
  return products.filter(
    (p) =>
      p.name.toLowerCase().includes(lowerQuery) ||
      p.shortDescription.toLowerCase().includes(lowerQuery) ||
      p.description.toLowerCase().includes(lowerQuery) ||
      p.categoryId.toLowerCase().includes(lowerQuery) ||
      p.specifications.category.toLowerCase().includes(lowerQuery) ||
      p.slug.toLowerCase().includes(lowerQuery) ||
      p.subcategoryId.toLowerCase().includes(lowerQuery)
  )
}

