function indexProductsIntoCategories() {
  for (const category of productCategories) {
    if (!category.subcategories) continue

    for (const subcategory of category.subcategories) {
      subcategory.products = []
    }
  }

  for (const product of products) {
    const category = productCategories.find((item) => item.id === product.categoryId)
    const subcategory = category?.subcategories?.find(
      (item) => item.id === product.subcategoryId
    )

    if (subcategory) {
      subcategory.products.push(product)
    }
  }
}

indexProductsIntoCategories()
